/**
 * @file validate-midi.mjs
 * @description Closed-loop validator for src/lib/data/midi.json (the S-1 MIDI implementation)
 *
 * Every number in midi.json must be backed by the official manual corpus
 * (generated by `npm run docs:sync`):
 * 1. Each citation quote exists verbatim on the cited page.
 * 2. Each control change entry's quote is the exact line of the manual's "Control change list"
 *    and starts with "<CC number> <parameter>", so no CC number or name is guessed; every CC in
 *    that list must be present (nothing silently dropped).
 * 3. Transmit/receive flags are re-parsed from the chart quotes: the chart lists every
 *    Transmitted value of a block before its Recognized values ("o" = yes, "x" = no).
 * 4. Panel mappings use real faceplate control IDs; each knob has at most one knob-layer CC.
 */

import fs from 'node:fs';
import path from 'node:path';
import { VALID_BUTTON_IDS, isKnobId } from '../src/lib/device.js';

const MIDI_PATH = path.resolve('src/lib/data/midi.json');
const SOURCES_PATH = path.resolve('docs/reference/sources.json');
const LAYERS = new Set(['knob', 'shift-knob', 'function', 'performance']);
const MAX_QUOTE_LENGTH = 240;

const { sources } = JSON.parse(fs.readFileSync(SOURCES_PATH, 'utf8'));
const DOC_PREFIXES = sources.map((s) => `docs/reference/${s.slug}/`);
const missingCorpora = sources.filter(
	(s) => !fs.existsSync(path.resolve('docs/reference', s.slug, 'INDEX.md'))
);
if (missingCorpora.length > 0) {
	console.error('❌ Manual corpus not found. Run `npm run docs:sync` first.');
	process.exit(1);
}

const normalizeWhitespace = (str) => str.replace(/\s+/g, ' ').trim();
const docCache = new Map();

function getRawPage(docRelPath, pageNum) {
	if (!docCache.has(docRelPath)) {
		const absPath = path.resolve(docRelPath);
		docCache.set(docRelPath, fs.existsSync(absPath) ? fs.readFileSync(absPath, 'utf8') : null);
	}
	const content = docCache.get(docRelPath);
	if (!content) return null;
	const marker = `<!-- [Page ${pageNum}] -->`;
	const start = content.indexOf(marker);
	if (start === -1) return null;
	const next = content.indexOf('<!-- [Page ', start + marker.length);
	return next === -1 ? content.slice(start) : content.slice(start, next);
}

const errors = [];

/** Verifies a { doc, page, quote } citation and returns the normalized quote (or null). */
function checkCitation(label, citation) {
	if (!citation || typeof citation !== 'object') {
		errors.push(`${label}: missing citation.`);
		return null;
	}
	const { doc, page, quote } = citation;
	if (typeof doc !== 'string' || !DOC_PREFIXES.some((p) => doc.startsWith(p))) {
		errors.push(`${label}: citation.doc must be under ${DOC_PREFIXES.join(' or ')}.`);
		return null;
	}
	const raw = getRawPage(doc, page);
	if (raw === null) {
		errors.push(`${label}: page ${page} not found in ${doc}.`);
		return null;
	}
	const norm = normalizeWhitespace(String(quote ?? ''));
	if (norm.length < 2 || norm.length > MAX_QUOTE_LENGTH) {
		errors.push(`${label}: quote must be 2–${MAX_QUOTE_LENGTH} characters.`);
	}
	if (!normalizeWhitespace(raw).includes(norm)) {
		errors.push(`${label}: quote "${norm}" was NOT found on page ${page} of ${doc}.`);
		return null;
	}
	return norm;
}

/** "o"/"x" tokens that follow the last row label of a chart quote (Transmitted…, Recognized…). */
function chartTokens(quote, lastLabel) {
	const idx = quote.lastIndexOf(lastLabel);
	if (idx === -1) return null;
	return quote
		.slice(idx + lastLabel.length)
		.trim()
		.split(' ')
		.filter(Boolean);
}

const midi = JSON.parse(fs.readFileSync(MIDI_PATH, 'utf8'));

// 1. Basic channels
{
	const { synth, programChange, citation } = midi.channels ?? {};
	const quote = checkCitation('channels', citation);
	const expected = `${synth} (Synth), ${programChange} (Program Change)`;
	if (quote && quote.split(expected).length - 1 !== 2) {
		errors.push(
			`channels: quote must show "${expected}" as both the Transmitted and Recognized default.`
		);
	}
	for (const ch of [synth, programChange]) {
		if (!Number.isInteger(ch) || ch < 1 || ch > 16) errors.push(`channels: ${ch} is not 1–16.`);
	}
}

// 2. Non-CC message groups
for (const group of midi.messageGroups ?? []) {
	const label = `messageGroups "${group.group}"`;
	const quote = checkCitation(label, group.citation);
	if (!quote) continue;
	const rows = group.rows ?? [];
	if (rows.length === 0) {
		errors.push(`${label}: needs at least one row.`);
		continue;
	}
	for (const row of rows) {
		if (!quote.includes(row.message))
			errors.push(`${label}: row "${row.message}" is not in the quote.`);
	}
	if (group.remark !== undefined) {
		checkCitation(`${label} remark`, { ...group.citation, quote: group.remark });
	}
	const words = chartTokens(quote, rows.at(-1).message) ?? [];
	const ox = words.filter((w) => w === 'o' || w === 'x');
	if (ox.length === 2 * rows.length) {
		rows.forEach((row, i) => {
			const tx = ox[i] === 'o';
			const rx = ox[rows.length + i] === 'o';
			if (row.tx !== tx || row.rx !== rx) {
				errors.push(
					`${label}: "${row.message}" should be tx=${tx} rx=${rx} per the chart (got tx=${row.tx} rx=${row.rx}).`
				);
			}
		});
	} else if (ox.length === 0 && rows.length === 1 && rows[0].range) {
		const row = rows[0];
		if (words.join(' ') !== `${row.range} ${row.range}` || !row.tx || !row.rx) {
			errors.push(`${label}: range "${row.range}" must appear in both chart columns.`);
		}
	} else {
		errors.push(`${label}: could not read ${2 * rows.length} o/x chart values from the quote.`);
	}
	for (const row of rows) {
		if (row.range && ox.length > 0 && quote.split(row.range).length - 1 !== 2) {
			errors.push(`${label}: range "${row.range}" must appear in both chart columns.`);
		}
	}
}

// 3. Control change chart rows (Transmitted column first, then Recognized)
const chartRows = [];
{
	const quote = checkCitation('controlChangeChart', midi.controlChangeChart);
	const m = quote && /^Control Change ((?:\d+(?:–\d+|, \d+)? )+)((?:[ox] ?)+)$/.exec(quote);
	if (!m) {
		errors.push(
			'controlChangeChart: quote must be the "Control Change" rows followed by their o/x values.'
		);
	} else {
		const labels = m[1].trim().match(/\d+–\d+|\d+, \d+|\d+/g);
		const ox = m[2].trim().split(' ');
		if (ox.length !== labels.length * 2) {
			errors.push(
				`controlChangeChart: ${labels.length} rows need ${labels.length * 2} o/x values, found ${ox.length}.`
			);
		}
		labels.forEach((lbl, i) => {
			let ccs;
			if (lbl.includes('–')) {
				const [a, b] = lbl.split('–').map(Number);
				ccs = Array.from({ length: b - a + 1 }, (_, k) => a + k);
			} else {
				ccs = lbl.split(', ').map(Number);
			}
			chartRows.push({ label: lbl, ccs, tx: ox[i] === 'o', rx: ox[labels.length + i] === 'o' });
		});
	}
}

// 4. Control changes
const listedLines = new Map();
for (const page of new Set((midi.controlChanges ?? []).map((c) => c.citation?.page))) {
	const doc = midi.controlChanges.find((c) => c.citation?.page === page).citation.doc;
	const raw = getRawPage(doc, page) ?? '';
	const headerIdx = raw.indexOf('Control Change Explanation');
	if (headerIdx === -1) continue;
	for (const line of raw.slice(headerIdx).split('\n')) {
		const lm = /^(\d{1,3}) (\S.*)$/.exec(line.trim());
		if (lm) listedLines.set(Number(lm[1]), line.trim());
	}
}

const seenCc = new Set();
const knobOwners = new Map();
for (const entry of midi.controlChanges ?? []) {
	const label = `CC ${entry.cc}`;
	if (!Number.isInteger(entry.cc) || entry.cc < 0 || entry.cc > 127) {
		errors.push(`${label}: CC number must be an integer 0–127.`);
		continue;
	}
	if (seenCc.has(entry.cc)) errors.push(`${label}: duplicate entry.`);
	seenCc.add(entry.cc);

	const quote = checkCitation(label, entry.citation);
	if (quote) {
		if (!quote.startsWith(`${entry.cc} ${entry.parameter}`)) {
			errors.push(`${label}: quote must start with "${entry.cc} ${entry.parameter}".`);
		}
		if (listedLines.get(entry.cc) !== quote) {
			errors.push(`${label}: quote must be the exact line of the manual's control change list.`);
		}
	}

	const rowsForCc = chartRows.filter((r) => r.ccs.includes(entry.cc));
	if (rowsForCc.length !== 1) {
		errors.push(`${label}: must fall in exactly one row of the MIDI implementation chart.`);
	} else if (rowsForCc[0].tx !== entry.tx || rowsForCc[0].rx !== entry.rx) {
		errors.push(
			`${label}: chart row "${rowsForCc[0].label}" says tx=${rowsForCc[0].tx} rx=${rowsForCc[0].rx}.`
		);
	}

	if (!LAYERS.has(entry.layer))
		errors.push(`${label}: layer must be one of ${[...LAYERS].join(', ')}.`);
	const controls = Array.isArray(entry.controls) ? entry.controls : [];
	for (const id of controls) {
		if (!VALID_BUTTON_IDS.has(id)) errors.push(`${label}: unknown faceplate control "${id}".`);
	}
	if (entry.layer === 'knob') {
		if (controls.length !== 1 || !isKnobId(controls[0])) {
			errors.push(`${label}: a knob-layer CC must map to exactly one knob.`);
		} else if (knobOwners.has(controls[0])) {
			errors.push(`${label}: knob ${controls[0]} already sends CC ${knobOwners.get(controls[0])}.`);
		} else {
			knobOwners.set(controls[0], entry.cc);
		}
	} else if (entry.layer === 'performance' && controls.length > 0) {
		errors.push(`${label}: performance controllers have no panel control.`);
	} else if (entry.layer !== 'performance' && controls.length === 0) {
		errors.push(`${label}: map it to at least one faceplate control.`);
	}
}

for (const cc of listedLines.keys()) {
	if (!seenCc.has(cc))
		errors.push(`CC ${cc}: listed in the manual's control change list but missing from midi.json.`);
}

if (errors.length > 0) {
	console.error('❌ MIDI validation failed:\n' + errors.map((e) => `  - ${e}`).join('\n'));
	process.exit(1);
}

console.log(
	`✔ Validated S-1 MIDI implementation: ${seenCc.size} control changes (${knobOwners.size} knob CCs), ${midi.messageGroups.length} message groups, default channel ${midi.channels.synth} — all quoted verbatim from the manual.`
);
